BASE_SECOND.update({'ru':'Ссылка Таблица открывает главный каталог kakobuymake.com в отдельной вкладке.','ar':'يفتح رابط جدول المنتجات الكتالوج الرئيسي kakobuymake.com في علامة تبويب منفصلة.','tr':'Ürün tablosu bağlantısı ana katalog kakobuymake.com’u ayrı sekmede açar.','ja':'スプレッドシートのリンクは、主カタログのkakobuymake.comを別タブで開きます。','ko':'스프레드시트 링크는 메인 목록 kakobuymake.com을 별도 탭에서 엽니다.'})

def apply():
 p=r/'content.json';d=json.load(open(p));assert set(d)==set(FULL)|set(EXTRA)
 for code,t in d.items():
  if code in FULL:
   assert len(FULL[code])==12
   t['questions']=[[q,a] for (q,_),a in zip(t['questions'],FULL[code])]
  else:
   assert len(EXTRA[code])==12
   for i,pair in enumerate(t['questions']):
    base=BASE_SECOND[code] if i==1 else pair[1].split('\n\n')[0]
    pair[1]=base+'\n\n'+EXTRA[code][i]
  assert len(t['questions'])==12 and all('\n\n' in a for q,a in t['questions'])
 json.dump(d,open(p,'w'),ensure_ascii=False,indent=2)
 print('Expanded FAQ for',len(d),'languages; total answers',sum(len(t['questions']) for t in d.values()))
 print('English answer word range:',min(len(a.split()) for q,a in d['en']['questions']),max(len(a.split()) for q,a in d['en']['questions']))
 print('Chinese answer character range:',min(len(a) for q,a in d['zh-CN']['questions']),max(len(a) for q,a in d['zh-CN']['questions']))
if __name__=='__main__':apply()
